<template>
  <section class="page">
    <header><div><h1>案例库</h1><p>用户提供的年度案例汇编；非最高人民法院指导案例。每条结果保留原始页码，供人工复核。</p></div><el-button @click="load">刷新</el-button></header>
    <el-alert v-if="error" type="error" :title="error" show-icon :closable="false" />
    <el-card shadow="never" class="source-card"><template #header>案例来源与 OCR 状态</template><el-table :data="sources" v-loading="loading" size="small"><el-table-column prop="title" label="来源" min-width="320" /><el-table-column prop="domain" label="领域" width="120" /><el-table-column label="进度" width="190"><template #default="{ row }"><el-progress :percentage="percent(row)" :status="row.status === 'COMPLETED' ? 'success' : undefined" /></template></el-table-column><el-table-column prop="status" label="状态" width="130" /></el-table></el-card>
    <el-card shadow="never"><template #header><div class="filter"><span>结构化案例</span><el-select v-model="domain" clearable placeholder="全部领域" @change="loadCases"><el-option label="劳动" value="labor" /><el-option label="公司" value="company" /><el-option label="刑事" value="criminal" /><el-option label="知识产权" value="intellectual_property" /></el-select></div></template><el-table :data="cases" v-loading="loading" empty-text="暂无已完成结构化的案例。"><el-table-column prop="title" label="案例" min-width="250" /><el-table-column prop="case_cause" label="案由" min-width="160" /><el-table-column label="资料" width="100"><template #default="{ row }"><el-tag :type="row.metadata_complete ? 'success' : 'warning'">{{ row.metadata_complete ? '完整' : '有缺项' }}</el-tag></template></el-table-column><el-table-column label="原文页码" width="120"><template #default="{ row }">{{ row.source_start_page }}–{{ row.source_end_page }}</template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{ row }"><el-button text type="primary" @click="open(row.id)">详情</el-button></template></el-table-column></el-table></el-card>
    <el-drawer v-model="visible" size="560px" title="案例详情"><template v-if="selected"><h2>{{ selected.title || '未识别标题' }}</h2><el-tag>{{ selected.case_cause }}</el-tag><p><b>案号：</b>{{ selected.case_number || '未提取' }}</p><p><b>法院：</b>{{ selected.court_name || '未提取' }}</p><p><b>裁判日期：</b>{{ selected.judgment_date || '未提取' }}</p><p><b>原文页码：</b>{{ selected.source_start_page }}–{{ selected.source_end_page }}</p><el-alert v-if="selected.missing_fields.length" type="warning" :title="`资料缺项：${selected.missing_fields.map(fieldLabel).join('、')}`" :closable="false" /><h3>案件焦点</h3><p>{{ selected.issues || '未提取' }}</p><h3>法院裁判理由</h3><p>{{ selected.court_reasoning || '未提取' }}</p><h3>裁判结果</h3><p>{{ selected.judgment_result || '未提取' }}</p><el-alert v-for="warning in selected.extraction_warnings" :key="warning" type="warning" :title="warning" :closable="false" /><h3>相似案例</h3><el-empty v-if="similar.length === 0" description="暂无相似案例" /><el-link v-for="item in similar" :key="item.id" class="similar" @click="open(item.id)">{{ item.title || item.id }} · {{ item.case_cause }} · {{ item.similarity_score.toFixed(2) }}</el-link></template></el-drawer>
  </section>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { caseApi, type CaseSource, type LegalCase } from '@/api/cases'
const sources = ref<CaseSource[]>([]); const cases = ref<LegalCase[]>([]); const domain = ref(''); const loading = ref(false); const error = ref(''); const visible = ref(false); const selected = ref<LegalCase>(); const similar = ref<Array<LegalCase & { similarity_score: number; case_cause_match: boolean }>>([])
const percent = (source: CaseSource) => source.page_count ? Math.round(source.processed_pages / source.page_count * 100) : 0
const fieldLabel = (field: string) => ({ case_number: '案号', court_name: '法院', judgment_date: '裁判日期', court_reasoning: '裁判要旨' }[field] || field)
async function loadCases() { cases.value = await caseApi.list({ domain: domain.value || undefined }) }
async function load() { loading.value = true; error.value = ''; try { sources.value = await caseApi.sources(domain.value || undefined); await loadCases() } catch { error.value = '案例库加载失败，请确认后端服务已启动。' } finally { loading.value = false } }
async function open(id: string) { selected.value = await caseApi.detail(id); similar.value = await caseApi.similar(id).catch(() => []); visible.value = true }
onMounted(load)
</script>
<style scoped>.page { max-width: 1240px; margin: 0 auto; } header { margin-bottom: 24px; display: flex; justify-content: space-between; align-items: flex-start; } h1 { margin: 0; color: #0f1f3d; font-family: 'Noto Serif SC', STSong, serif; } h2 { color: #0f1f3d; } p { color: #606266; line-height: 1.75; white-space: pre-wrap; } .source-card { margin: 16px 0; } .filter { display: flex; align-items: center; justify-content: space-between; } .similar { display: block; margin: 10px 0; }</style>
